<section class="glass panel academic-release"><div class="academic-panel-heading"><div class="grade-section-title"><span class="grade-section-icon is-send"><?php echo academic_ui_icon('send'); ?></span><div><h2>Grade release</h2><p>Review the calculated grades, publish a student release, then finalize when every period is complete.</p></div></div><span class="academic-status"><?php echo !empty($book['locked']) ? 'Finalized · locked' : ($book['published'] ? 'Published' : 'Draft'); ?></span></div>

<?php if (!empty($book['locked'])): ?>
<form method="post" class="academic-inline-form"><?php render_grade_form_fields($book); ?><input type="hidden" name="action" value="unlock"><label><span>Reason for reopening grades</span><input name="reason" maxlength="500" required></label><button class="button button-secondary">Unlock for Correction</button></form>
<?php else: ?>
<div class="academic-release-grid"><form method="post" class="stack-form"><?php render_grade_form_fields($book); ?><input type="hidden" name="action" value="review"><span class="grade-step-art"><?php echo academic_ui_icon('book'); ?></span><h3><span class="grade-step-number">1</span>Review</h3><p>Confirm you have checked the calculated grades and assessments.</p><button class="button button-secondary"><?php echo academic_ui_icon('check'); ?>Mark Grades Reviewed</button></form>
<form method="post" class="stack-form"><?php render_grade_form_fields($book); ?><input type="hidden" name="action" value="publish"><span class="grade-step-art"><?php echo academic_ui_icon('send'); ?></span><h3><span class="grade-step-number">2</span>Publish</h3><p>Release the reviewed grades to students.</p><label class="grade-confirm"><input type="checkbox" name="confirm" value="yes" required><span>Release the reviewed grades to students</span></label><button class="button button-primary"><?php echo academic_ui_icon('send'); ?>Release Grades</button></form>
<form method="post" class="stack-form"><?php render_grade_form_fields($book); ?><input type="hidden" name="action" value="lock"><span class="grade-step-art"><?php echo academic_ui_icon('lock'); ?></span><h3><span class="grade-step-number">3</span>Finalize</h3><p>Finalize this release and lock grade editing.</p><label class="grade-confirm"><input type="checkbox" name="confirm" value="yes" required><span>Finalize this release and lock grade editing</span></label><button class="button button-secondary"><?php echo academic_ui_icon('lock'); ?>Finalize &amp; Lock</button></form></div>
<?php if ($book['published']): ?><details><summary>Hide published release</summary><form method="post" class="academic-inline-form"><?php render_grade_form_fields($book); ?><input type="hidden" name="action" value="unpublish"><label class="grade-confirm"><input type="checkbox" name="confirm" value="yes" required><span>Confirm hiding published grades</span></label><button class="button button-secondary">Hide Grades</button></form></details><?php endif; ?>
<?php endif; ?></section>
